use vstd::prelude::*;

verus! {

    /// Specification of the table count function.
    /// Given three natural numbers a,b,c, the max number of tables without any monochromatic table
    /// is min( floor((a+b+c)/3), a+b, a+c, b+c ).
    /// The floor division is integer division.
    spec fn max_tables(a: nat, b: nat, c: nat) -> nat {
        let total := (a + b + c) / 3;
        let ab := a + b;
        let ac := a + c;
        let bc := b + c;
        total.min(ab.min(ac.min(bc)))
    }

    /// Main function solving the problem.
    /// Input: r,g,b are i8 with values in [0..127] (nonnegative).
    /// Output is i8 giving the computed max number of tables.
    fn solve(r: i8, g: i8, b: i8) -> i8
        requires
            0 <= r && r <= 127,
            0 <= g && g <= 127,
            0 <= b && b <= 127,
        ensures
            ret >= 0,
            ret as nat == max_tables(r as nat, g as nat, b as nat),
    {
        // Convert inputs to nat
        let a: nat = r as nat;
        let b_: nat = g as nat;
        let c: nat = b as nat;

        // Compute parts
        let total = (a + b_ + c) / 3;
        let ab = a + b_;
        let ac = a + c;
        let bc = b_ + c;

        // Compute min of these values
        let mut res: nat = total;
        if ab < res {
            res = ab;
        }
        if ac < res {
            res = ac;
        }
        if bc < res {
            res = bc;
        }

        res as i8
    }
}

